USE saudi_ecommerce;
CREATE OR REPLACE VIEW vw_order_header AS SELECT o.*,c.city,c.region,c.customer_segment,CASE WHEN o.order_status='Delivered' THEN o.order_total_sar ELSE 0 END delivered_sales_sar,CASE WHEN o.order_status='Delivered' THEN 1 ELSE 0 END delivered_flag,CASE WHEN o.order_status='Cancelled' THEN 1 ELSE 0 END cancelled_flag,CASE WHEN o.order_status='Returned' THEN 1 ELSE 0 END returned_flag FROM orders o JOIN customers c ON c.customer_id=o.customer_id;
CREATE OR REPLACE VIEW vw_delivery_performance AS SELECT d.*,o.order_date,c.city customer_city,CASE WHEN d.delivery_status='Delivered' AND d.actual_days>d.promised_days THEN 1 ELSE 0 END late_flag,CASE WHEN d.delivery_status='Delivered' THEN 1 ELSE 0 END delivered_flag FROM deliveries d JOIN orders o ON o.order_id=d.order_id JOIN customers c ON c.customer_id=o.customer_id;
CREATE OR REPLACE VIEW vw_item_margin AS SELECT i.*,p.category,p.subcategory,o.order_date,o.order_status,(i.line_revenue_sar-i.quantity*i.unit_cost_sar) pre_discount_item_margin_sar FROM order_items i JOIN products p ON p.product_id=i.product_id JOIN orders o ON o.order_id=i.order_id;
-- Avoid summing order header revenue after joining to order items.
